import { activeOverrides } from "#app/overrides";
import { CHEAT_DEFS, getCheatValue, saveCheats, setCheatValue } from "#app/cheat-config";

const PANEL_ID = "pgCheatPanel";
const BTN_ID = "pgCheatBtn";

function writeOverride(key: string, value: unknown): void {
  (activeOverrides as unknown as Record<string, unknown>)[key] = value;
}

/** 在页面右下角安装"金手指面板" */
export function installCheatPanel(): void {
  if (document.getElementById(BTN_ID)) {
    return;
  }

  const style = document.createElement("style");
  style.textContent =
    "#" + BTN_ID + "{position:fixed;right:10px;bottom:62px;z-index:99999;width:42px;height:42px;border-radius:50%;" +
    "background:rgba(0,0,0,0.4);color:#fff;font-size:20px;line-height:42px;text-align:center;cursor:pointer;" +
    "user-select:none;touch-action:manipulation;opacity:0.55;}" +
    "#" + PANEL_ID + "{position:fixed;right:10px;bottom:112px;z-index:99999;width:300px;max-height:68vh;overflow:auto;" +
    "background:rgba(22,22,28,0.95);border:1px solid #6a6a78;border-radius:10px;color:#eee;" +
    "font:13px/1.5 system-ui,-apple-system,'Microsoft YaHei',sans-serif;padding:8px 10px;display:none;" +
    "touch-action:manipulation;box-shadow:0 6px 24px rgba(0,0,0,0.5);}" +
    "#" + PANEL_ID + ".pgShow{display:block;}" +
    "#" + PANEL_ID + " h3{margin:2px 0 6px;font-size:14px;color:#ffd75e;}" +
    "#" + PANEL_ID + " .pgHint{font-size:11px;color:#9aa0ad;margin-bottom:6px;}" +
    "#" + PANEL_ID + " .pgRow{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:5px 0;" +
    "border-bottom:1px solid rgba(255,255,255,0.08);}" +
    "#" + PANEL_ID + " .pgLabel{flex:1;}" +
    "#" + PANEL_ID + " .pgTag{font-size:11px;color:#8fd7ff;}" +
    "#" + PANEL_ID + " .pgBtn{flex:0 0 auto;min-width:66px;text-align:center;padding:3px 8px;border-radius:11px;" +
    "background:#3a3a46;color:#fff;cursor:pointer;user-select:none;font-size:12px;}" +
    "#" + PANEL_ID + " .pgBtn:active{background:#5a5a6a;}";
  document.head.appendChild(style);

  const btn = document.createElement("div");
  btn.id = BTN_ID;
  btn.textContent = "\u2699\uFE0F";

  const root = document.createElement("div");
  root.id = PANEL_ID;

  const title = document.createElement("h3");
  title.textContent = "金手指（改完立即生效，自动保存）";
  root.appendChild(title);

  const hint = document.createElement("div");
  hint.className = "pgHint";
  hint.textContent = "带「新开一局」标记的项，只对之后新开的存档生效。";
  root.appendChild(hint);

  const renders: Array<() => void> = [];

  for (const def of CHEAT_DEFS) {
    const row = document.createElement("div");
    row.className = "pgRow";

    const label = document.createElement("div");
    label.className = "pgLabel";
    label.textContent = def.label;
    if (def.newRunOnly) {
      const tag = document.createElement("span");
      tag.className = "pgTag";
      tag.textContent = " 新开一局";
      label.appendChild(tag);
    }
    row.appendChild(label);

    const valueBtn = document.createElement("div");
    valueBtn.className = "pgBtn";

    const render = () => {
      const v = getCheatValue(def.key);
      if (def.kind === "toggle") {
        valueBtn.textContent = v ? "开" : "关";
        valueBtn.style.background = v ? "#2f7d32" : "#3a3a46";
      } else {
        const opts = def.options ?? [];
        const labels = def.optionLabels ?? opts.map(o => String(o));
        const idx = opts.findIndex(o => o === v);
        valueBtn.textContent = idx >= 0 ? labels[idx] : String(v);
        valueBtn.style.background = "#3a3a46";
      }
    };

    valueBtn.addEventListener("click", () => {
      const cur = getCheatValue(def.key);
      let next: boolean | number | null;
      if (def.kind === "toggle") {
        next = !cur;
      } else {
        const opts = def.options ?? [];
        const idx = opts.findIndex(o => o === cur);
        next = opts[(idx + 1) % opts.length];
      }
      setCheatValue(def.key, next);
      writeOverride(def.key, next);
      saveCheats();
      render();
    });

    render();
    renders.push(render);
    row.appendChild(valueBtn);
    root.appendChild(row);
  }

  const resetRow = document.createElement("div");
  resetRow.className = "pgRow";
  const spacer = document.createElement("div");
  spacer.className = "pgLabel";
  spacer.textContent = "一键恢复默认";
  resetRow.appendChild(spacer);
  const resetBtn = document.createElement("div");
  resetBtn.className = "pgBtn";
  resetBtn.textContent = "重置";
  resetBtn.addEventListener("click", () => {
    for (const def of CHEAT_DEFS) {
      setCheatValue(def.key, def.def);
      writeOverride(def.key, def.def);
    }
    saveCheats();
    for (const r of renders) {
      r();
    }
  });
  resetRow.appendChild(resetBtn);
  root.appendChild(resetRow);

  btn.addEventListener("click", () => root.classList.toggle("pgShow"));

  document.body.appendChild(btn);
  document.body.appendChild(root);

  // 把配置同步一遍（确保与当前 activeOverrides 一致）
  for (const def of CHEAT_DEFS) {
    writeOverride(def.key, getCheatValue(def.key));
  }
}
