      moveset: string[];
      /** @since 2.0.0 */
      tempMoveset: string[];
      /** @since 2.0.0 */
      ability: string;
      /** @since 2.0.0 */
      tempAbility: string;
      /** @since 2.0.0 */
      passiveAbility: string;
      /** @since 2.0.0 */
