import { installCheatPanel } from "#app/cheat-panel";
import { globalScene } from "#app/global-scene";
import { Button } from "#enums/buttons";
import { UiMode } from "#enums/ui-mode";

/** A tappable region mapped to a cursor index of the active UI handler. */
export interface TouchRect {
  index: number;
  x: number;
  y: number;
  w: number;
  h: number;
}

let installed = false;

/** Handle a tap/click at world coordinates. Returns true if it selected an option. */
export function handleTapPoint(x: number, y: number): boolean {
  const scene: any = globalScene;
  const ui: any = scene?.ui;
  if (!ui?.getHandler) {
    return false;
  }
  const handler: any = ui.getHandler();

  let rects: TouchRect[] | null = null;
  if (handler?.getTouchRects) {
    try {
      rects = handler.getTouchRects();
    } catch (e) {
      console.error("[direct-touch] getTouchRects failed", e);
      rects = null;
    }
  }

  if (rects?.length) {
    let best: TouchRect | null = null;
    for (const r of rects) {
      if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) {
        if (!best || r.w * r.h < best.w * best.h) {
          best = r;
        }
      }
    }
    if (best) {
      try {
        scene.inputMethod = "touch";
        if (typeof (best as any).action === "function") {
          (best as any).action();
        } else {
          ui.setCursor(best.index);
          ui.processInput(Button.ACTION);
        }
      } catch (e) {
        console.error("[direct-touch] select failed", e);
        return false;
      }
      return true;
    }
  }

  // Fallback: advance a plain message/dialogue on tap.
  if (ui.mode === UiMode.MESSAGE) {
    try {
      scene.inputMethod = "touch";
      ui.processInput(Button.ACTION);
      return true;
    } catch {}
  }

  return false;
}

/** Install the direct-touch input layer, replacing the built-in virtual gamepad. */
export function installDirectTouch(scene: Phaser.Scene): void {
  if (installed) {
    return;
  }
  installed = true;

  // Hide the built-in virtual gamepad (D-pad + A/B); direct touch replaces it.
  const style = document.createElement("style");
  style.textContent =
    "#touchControls{display:none !important;}" +
    "body.pg-show-pad #touchControls{display:block !important;}" +
    "#pgPadToggle{position:fixed;right:10px;bottom:10px;z-index:99999;width:42px;height:42px;" +
    "border-radius:50%;background:rgba(0,0,0,0.4);color:#fff;font-size:20px;line-height:42px;" +
    "text-align:center;cursor:pointer;user-select:none;touch-action:manipulation;opacity:0.55;}";
  document.head.appendChild(style);

  scene.input.on("pointerdown", (pointer: Phaser.Input.Pointer) => {
    const ui: any = (globalScene as any)?.ui;
    if (!ui?.getHandler) {
      return;
    }
    handleTapPoint(pointer.x, pointer.y);
  });

  // 金手指面板
  installCheatPanel();

  // Floating toggle: reveal the built-in D-pad for screens without direct-touch support.
  const btn = document.createElement("div");
  btn.id = "pgPadToggle";
  btn.textContent = "\u{1F3AE}";
  btn.addEventListener("click", () => {
    document.body.classList.toggle("pg-show-pad");
  });
  document.body.appendChild(btn);

  // Debug hook for tuning tap targets in a live session.
  try {
    (window as any).__pg = {
      get scene() {
        return globalScene;
      },
      get ui() {
        return (globalScene as any).ui;
      },
      tap: (x: number, y: number) => handleTapPoint(x, y),
      rects: () => (globalScene as any)?.ui?.getHandler?.()?.getTouchRects?.() ?? null,
    };
  } catch {}
}
